function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 10000) return 'nums needs 1 to 10^4 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -10000000 || v > 10000000)) return 'Each value is an integer between -10^7 and 10^7.';
  if (!Number.isInteger(k) || k < 0 || k > 10000000) return 'k is an integer between 0 and 10^7.';
  return null;
}

