function findPairs(nums, k) {
  const count = new Map();
  for (const num of nums) {
    count.set(num, (count.get(num) ?? 0) + 1);
  }
  let pairs = 0;
  for (const [value, times] of count) {
    if (k === 0) {
      if (times > 1) {
        pairs++;
      }
    } else if (count.has(value + k)) {
      pairs++;
    }
  }
  return pairs;
}

