function findPairs(nums, k) {
  // Try every pair of positions and remember each value pair as "smaller,larger".
  const found = new Set();
  for (let i = 0; i < nums.length; i++)
    for (let j = 0; j < nums.length; j++)
      if (i !== j && Math.abs(nums[i] - nums[j]) === k) found.add(Math.min(nums[i], nums[j]) + ',' + Math.max(nums[i], nums[j]));
  return found.size;
}

