function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 10), span = int(1, 6);
    return [Array.from({ length: n }, () => int(-span, span)), rand() < 0.3 ? 0 : int(0, 2 * span + 1)];
  }
  const n = 2000;
  const mode = rand();
  if (mode < 0.4) {
    // Dense values: many duplicates and many hits for small k.
    return [Array.from({ length: n }, () => int(-1500, 1500)), rand() < 0.3 ? 0 : int(1, 40)];
  }
  if (mode < 0.7) {
    // Values on a coarse grid across the full range, k a multiple of the step.
    const step = int(1000, 50000);
    const top = Math.floor(10000000 / step);
    return [Array.from({ length: n }, () => int(-top, top) * step), step * int(1, 5)];
  }
  // Sparse values across the full range with a large k.
  return [Array.from({ length: n }, () => int(-10000000, 10000000)), int(0, 10000000)];
}
